"use strict";
const retroDevices={mp3:{name:'闪存 MP3',year:1998,tag:'128MB / USB / MUSIC',class:'flash-mp3'},mp4:{name:'彩屏 MP4',year:2004,tag:'2.4 INCH / VIDEO PLAYER',class:'video-mp4'},dict:{name:'电子词典',year:1996,tag:'ENGLISH / STUDY / MEMO',class:'study-dict'}};
const pocketWords=[['hello','你好；喂'],['memory','记忆；回忆'],['summer','夏天'],['friend','朋友'],['music','音乐'],['story','故事'],['dream','梦；梦想'],['school','学校'],['rain','雨'],['night','夜晚'],['phone','电话；手机'],['world','世界'],['home','家；家园'],['letter','信；字母'],['light','光；明亮的'],['time','时间'],['book','书'],['game','游戏'],['hope','希望'],['tomorrow','明天']];
let retroDevice={model:'mp3',on:false,locked:false,view:'menu',index:0,volume:5,brightness:2,repeat:'all',word:'',photo:0};
try{const p=JSON.parse(localStorage.getItem('archaeo-device-os')||'{}');if(Object.hasOwn(retroDevices,p.model))retroDevice.model=p.model;if(Number.isInteger(p.volume)&&p.volume>=0&&p.volume<=10)retroDevice.volume=p.volume;if([1,2,3].includes(p.brightness))retroDevice.brightness=p.brightness;}catch{}
function saveRetroDevice(){try{localStorage.setItem('archaeo-device-os',JSON.stringify({model:retroDevice.model,volume:retroDevice.volume,brightness:retroDevice.brightness}));}catch{}}
function deviceMenu(){return retroDevice.model==='dict'?['英汉词典','单词记忆','阅读本','设置','设备信息']:retroDevice.model==='mp4'?['音乐播放','视频播放','图片浏览','阅读本','设置','USB连接','设备信息']:['音乐播放','文件浏览','阅读本','设置','USB连接','设备信息'];}
function deviceOptions(){const v=retroDevice.view;if(v==='menu')return deviceMenu();if(v==='music'||v==='files')return memoryTracks.map(t=>t.name+'.mp3');if(v==='videos')return eraFilms.filter(f=>f.year<=Number(year())).map(f=>f.title);if(v==='dictionary')return pocketWords.filter(w=>w[0].includes(retroDevice.word.toLowerCase())).map(w=>w[0]);if(v==='settings')return [`音量 ${retroDevice.volume}/10`,`屏幕亮度 ${retroDevice.brightness}/3`,`循环 ${retroDevice.repeat==='one'?'单曲':'全部'}`];return [];}
function deviceTime(t){if(!Number.isFinite(t)||t<0)t=0;return `${Math.floor(t/60).toString().padStart(2,'0')}:${Math.floor(t%60).toString().padStart(2,'0')}`;}
function deviceScreen(){const d=retroDevice,a=$('#retro-audio');if(!d.on)return '<div class="gadget-off">按 POWER 开机</div>';if(d.booting)return '<div class="gadget-boot"><b>OLD DAYS</b><p>DIGITAL LIFE</p><small>启动中…</small></div>';const opts=deviceOptions();if(opts.length)d.index=Math.max(0,Math.min(d.index,opts.length-1));let body='';if(d.view==='playing')body=`<div class="gadget-now"><small>MP3 · STEREO</small><h3>${escapeHTML(memoryTracks[memoryTrack].name)}</h3><div class="gadget-eq">▂ ▄ ▆ ▃ ▇ ▅ ▂ ▆</div><p data-gadget-time>${deviceTime(a.currentTime)} / ${deviceTime(a.duration)}</p><progress data-gadget-progress max="100" value="0"></progress><p>${a.paused?'Ⅱ PAUSE':'▶ PLAY'} · VOL ${d.volume} · ${d.repeat==='one'?'REPEAT 1':'REPEAT ALL'}</p></div>`;else if(d.view==='video'){const f=eraFilms.filter(f=>f.year<=Number(year()))[d.index];body=f?`<video id="gadget-video" controls playsinline preload="metadata" src="${f.src}" aria-label="MP4屏幕视频"></video><small>${escapeHTML(f.title)} · 流媒体演示</small>`:'<p>该年份还没有收录影片</p>';}else if(d.view==='photos')body=`<img class="gadget-photo" src="images/memories/${['night','campus','station','portrait'][d.photo]}.jpg" alt="怀旧原创配图"><small>PHOTO ${d.photo+1}/4 · AI原创配图</small>`;else if(d.view==='books')body='<h3>夜读记事本</h3><p>晚自习以后，路灯一盏一盏亮起来。把耳机线从校服袖子里抽出来，一首歌还没放完，家门已经到了。</p><p>那时候容量很小，能装下的歌不多。喜欢的文字要手动存成TXT，怕别人碰坏屏幕，也怕自己不小心按下删除。</p><p>再听一遍，就睡觉。明天还要早起，今晚的月亮却舍不得关。</p><small>本站原创 · 下键滚动 / M返回</small>';else if(d.view==='definition'){const w=pocketWords.find(w=>w[0]===d.word);body=`<h2>${escapeHTML(w?.[0]||d.word)}</h2><p>${escapeHTML(w?.[1]||'词库未收录')}</p><p>记忆提示：${d.word==='memory'?'Keep this memory. 留住这段回忆。':'把这个词抄进笔记本，再读一遍。'}</p><small>20词离线体验词库</small>`;}else if(d.view==='usb')body='<div class="gadget-usb">↔<h3>USB 模式</h3><p>本机界面模拟</p><p>没有连接电脑或访问磁盘</p><small>按 M 退出</small></div>';else if(d.view==='info')body=`<h3>系统信息</h3><p>OLD DAYS OS 1.0</p><p>${retroDevices[d.model].tag}</p><p>内置文件：4首原创配乐</p><small>容量为外观设定，文件来自本站；非原厂固件。</small>`;else body=`${d.view==='dictionary'?'<form id="gadget-dictionary"><input id="gadget-word" aria-label="查询英文单词" maxlength="30" value="${escapeHTML(d.word)}" placeholder="输入单词 / 回车查询"><button>查词</button></form>':''}<ul>${opts.map((x,i)=>`<li><button data-gadget-select="${i}" class="${i===d.index?'selected':''}">${i===d.index?'▶':'·'} ${escapeHTML(x)}</button></li>`).join('')||'<li>没有可用文件</li>'}</ul>`;return `<div class="gadget-status"><span>${d.locked?'🔒 HOLD':'◀ STEREO'}</span><span>VOL ${d.volume} ▰▰▱</span></div><div id="gadget-body" class="gadget-body">${body}</div><div class="gadget-soft">M 返回 <span>▶ 确认</span></div>`;}
function renderDeviceLab(){if(retroDevices[retroDevice.model].year>Number(year()))retroDevice.model='dict';const d=retroDevice,m=retroDevices[d.model];return `<section class="gadget-lab"><nav><button data-action="home">‹ 时光首页</button><button data-phone-lab>旧手机</button><button data-capture-gadget>保存设备场景</button></nav><header><small>POCKET ELECTRONICS / 掌中设备馆</small><h1>口袋里，不只有手机。</h1><p>按下开机键，再摸一遍那些熟悉的菜单。</p></header><div class="gadget-models">${Object.entries(retroDevices).filter(([k,m])=>m.year<=Number(year())).map(([k,m])=>`<button data-gadget-model="${k}" class="${k===d.model?'selected':''}">${m.name}</button>`).join('')}</div><div class="gadget-stage"><div id="gadget-unit" class="gadget-unit ${m.class}"><div class="gadget-brand">OLD DAYS <small>${m.tag}</small></div><div class="gadget-display brightness-${d.brightness}" id="gadget-display">${deviceScreen()}</div><div class="gadget-controls"><button data-gadget-key="power">POWER</button><button data-gadget-key="hold">${d.locked?'解除锁键':'HOLD 锁键'}</button><button data-gadget-key="menu" aria-label="M 返回">M</button><button data-gadget-key="up">▲</button><button data-gadget-key="left">|◀</button><button data-gadget-key="ok">▶ / Ⅱ</button><button data-gadget-key="right">▶|</button><button data-gadget-key="down">▼</button><button data-gadget-key="voldown">VOL −</button><button data-gadget-key="volup">VOL ＋</button></div>${d.model==='dict'?`<div class="gadget-keyboard">${'QWERTYUIOPASDFGHJKLZXCVBNM'.split('').map(k=>`<button data-gadget-letter="${k.toLowerCase()}">${k}</button>`).join('')}<button data-gadget-letter="back">⌫</button><button data-gadget-letter="enter">ENTER</button></div>`:''}<div class="gadget-port">● PHONE　 ━ USB</div></div><aside><h2>${m.name}</h2><p>▲▼选菜单，▶确认，M返回。播放时左右切歌，VOL调音量；电子词典可查内置单词。</p><p>MP4能在屏幕内播放已收录的年代开放影像。播放需要网络。</p><p>音乐、亮度、循环和锁键均能操作；容量、USB连接与电池图标是界面模拟，不代表真实硬件状态。</p><small>原创交互模拟，非某品牌原厂系统或固件。</small></aside></div></section>`;}
function refreshGadget(){if(current.type!=='devices')return;const screen=$('#gadget-display');if(screen){screen.innerHTML=deviceScreen();screen.className='gadget-display brightness-'+retroDevice.brightness;}document.querySelectorAll('[data-gadget-key="hold"]').forEach(b=>b.textContent=retroDevice.locked?'解除锁键':'HOLD 锁键');saveRetroDevice();}
function gadgetPlay(index){setMemoryTrack(index);$('#retro-audio').volume=retroDevice.volume/10;$('#retro-audio').loop=retroDevice.repeat==='one';retroDevice.view='playing';refreshGadget();}
function gadgetSelect(i){const d=retroDevice;if(!d.on||d.locked)return;d.index=i;if(d.view==='music'||d.view==='files')return gadgetPlay(i);if(d.view==='videos'){d.view='video';return refreshGadget();}if(d.view==='dictionary'){d.word=deviceOptions()[i]||'';d.view='definition';return refreshGadget();}if(d.view==='settings'){if(i===0)d.volume=(d.volume+1)%11;if(i===1)d.brightness=d.brightness%3+1;if(i===2)d.repeat=d.repeat==='one'?'all':'one';$('#retro-audio').volume=d.volume/10;$('#retro-audio').loop=d.repeat==='one';return refreshGadget();}const key=deviceMenu()[i];d.index=0;d.view={'音乐播放':'music','文件浏览':'files','视频播放':'videos','图片浏览':'photos','阅读本':'books','设置':'settings','USB连接':'usb','设备信息':'info','英汉词典':'dictionary','单词记忆':'dictionary'}[key]||'menu';if(d.view==='dictionary')d.word='';refreshGadget();}
function gadgetKey(key){const d=retroDevice,a=$('#retro-audio'),video=$('#gadget-video');if(key==='hold'){d.locked=!d.locked;return refreshGadget();}if(d.locked)return toast('HOLD 已锁键，先解除锁键');if(key==='power'){d.on=!d.on;d.view='menu';d.index=0;if(!d.on){d.booting=false;a.pause();video?.pause();}else{d.booting=true;setTimeout(()=>{d.booting=false;refreshGadget();},650);}return refreshGadget();}if(!d.on)return toast('先按 POWER 开机');if(key==='volup'||key==='voldown'){d.volume=Math.max(0,Math.min(10,d.volume+(key==='volup'?1:-1)));a.volume=d.volume/10;if(video)video.volume=d.volume/10;if(d.view!=='video')refreshGadget();return;}if(key==='menu'){video?.pause();d.view='menu';d.index=0;return refreshGadget();}if(d.view==='video'){if(!video)return;if(key==='ok'){if(video.paused)video.play().catch(()=>toast('视频暂时无法播放'));else video.pause();}if(key==='right'&&Number.isFinite(video.duration))video.currentTime=Math.min(video.duration,video.currentTime+10);if(key==='left')video.currentTime=Math.max(0,video.currentTime-10);return;}if(d.view==='playing'){if(key==='ok'){if(a.paused)a.play().catch(()=>toast('请再按一次播放'));else a.pause();refreshGadget();}if(key==='left'||key==='right')gadgetPlay(memoryTrack+(key==='left'?-1:1));return;}if(d.view==='photos'&&(key==='left'||key==='right')){d.photo=(d.photo+(key==='left'?3:1))%4;return refreshGadget();}if(d.view==='books'&&(key==='up'||key==='down'))return $('#gadget-body').scrollBy({top:key==='up'?-100:100,behavior:'smooth'});const options=deviceOptions();if(key==='up'||key==='down'){d.index=(d.index+(key==='up'?options.length-1:1))%Math.max(1,options.length);refreshGadget();$('#gadget-body .selected')?.scrollIntoView({block:'nearest'});}if(key==='ok')gadgetSelect(d.index);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-gadget-open],[data-gadget-model],[data-gadget-key],[data-gadget-select],[data-gadget-letter]');if(!b)return;e.preventDefault();if(b.hasAttribute('data-gadget-open'))return navigate({type:'devices',name:'掌中电子设备馆',url:'archaeo://devices'});if(b.dataset.gadgetModel&&Object.hasOwn(retroDevices,b.dataset.gadgetModel)){$('#retro-audio').pause();retroDevice.model=b.dataset.gadgetModel;retroDevice.on=false;retroDevice.locked=false;retroDevice.view='menu';saveRetroDevice();return navigate(current,false);}if(b.dataset.gadgetLetter){if(!retroDevice.on||retroDevice.locked)return;const k=b.dataset.gadgetLetter;if(k==='enter'){retroDevice.view='definition';}else{if(retroDevice.view!=='dictionary'){retroDevice.word='';retroDevice.view='dictionary';}retroDevice.word=k==='back'?retroDevice.word.slice(0,-1):(retroDevice.word+k).slice(0,30);}return refreshGadget();}if(b.dataset.gadgetKey)return gadgetKey(b.dataset.gadgetKey);if(b.dataset.gadgetSelect!==undefined)gadgetSelect(Number(b.dataset.gadgetSelect));});
document.addEventListener('submit',e=>{if(e.target.id!=='gadget-dictionary')return;e.preventDefault();retroDevice.word=$('#gadget-word').value.trim().slice(0,30).toLowerCase();retroDevice.view='definition';refreshGadget();});
document.addEventListener('DOMContentLoaded',()=>{const a=$('#retro-audio');a.addEventListener('timeupdate',()=>{if(current.type!=='devices'||retroDevice.view!=='playing')return;const t=$('[data-gadget-time]'),p=$('[data-gadget-progress]');if(t)t.textContent=deviceTime(a.currentTime)+' / '+deviceTime(a.duration);if(p)p.value=Number.isFinite(a.duration)&&a.duration>0?a.currentTime/a.duration*100:0;});a.addEventListener('ended',()=>{if(current.type==='devices'&&retroDevice.on&&retroDevice.repeat==='all')gadgetPlay(memoryTrack+1);});});
